/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),
    properties: {
        _endCallback: null,
    },

    Init(row) {
        cc.find("reels", this.node).active = true;
        cc.find("reels_bg", this.node).active = true;
        this._gold_reel = cc.find("gold_reel", this.node.parent);
        cc.find("caise_kuang", this.node).active = true;
        cc.find("caise_kuang", this.node).getComponent(sp.Skeleton).setAnimation(0, row + "X" + row, true);
        cc.find("luoxia_lizi", this.node).active = false;
        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()

        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = this._cfg.col
        this._row = row;

        this._topAniNode = cc.find("top_ani", this.node)

        this.createReels(this._col,this._row);
        for (let reel of this._reels) {
            for (let i = 0; i < this._row; i++) {
                let symbol = reel.GetSymbolByRow(i);
                symbol.setAnimationToTop(false);
                symbol.ShowById(13);
            }
        }
    },

    OnReelSpinEnd:function(colIdx){
        let reel = this._reels[colIdx];
        for (let i = 0; i < this._row; i++) {
            let symbol = reel.GetSymbolByRow(i);
            if (symbol.GetShowId() === this._cfg.questionMarkId) {
                Global.SlotsSoundMgr.playEffect("flyUP");
                symbol.playWinAnimation();
                let oriSymbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx((this._row - i - 1) * this._cfg.col + colIdx + 1);
                if (oriSymbol) {
                    oriSymbol.ShowById(this._cfg.questionMarkId);
                    oriSymbol.playWinAnimation();
                }
                let fly_wenhao = cc.instantiate(cc.find("fly_wenhao", this.node.parent));
                fly_wenhao.active = true;
                fly_wenhao.parent = this.node.parent;
                let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                fly_wenhao.position = startPos;
                let endPos = cc.find("lundai/wheel/wheel_mask/index_1", this._gold_reel).convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                cc.tween(fly_wenhao)
                    .to(0.5, {position: endPos, scale: 1.1})
                    .to(0.2, {scale: 1})
                    .call(()=>{
                        cc.find("lundai/wheel/wheel_mask/index_1", this._gold_reel).getComponent("ImgSwitchCmp").setIndex(11);
                    })
                    .removeSelf()
                    .start();
            }

            if (symbol.GetShowId() === this._cfg.dollarId) {
                symbol.playWinAnimation();
                Global.SlotsSoundMgr.playEffect("jpfly");
                let fly_dollar = cc.instantiate(cc.find("fly_dollar", this.node.parent));
                fly_dollar.active = true;
                fly_dollar.parent = this.node.parent;
                let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                fly_dollar.position = startPos;
                let collect_node = cc.find("slots/collect_node", this.node.parent);
                let endPos = collect_node.convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                cc.tween(fly_dollar)
                    .to(0.5, {position: endPos})
                    .call(() => {
                        cc.vv.gameData.GetSlotsScript().addDollar();
                    })
                    .removeSelf()
                    .start();
            }
        }
    },

    createReels:function(col,row){
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this.node);
            if (!node.getComponent('BasketballKing_ExtraReel')) {
                let scp = node.addComponent('BasketballKing_ExtraReel')
                scp.Init(i,row,this._topAniNode)
                this._reels.push(scp)
            }
        }
    },

    async startSlot() {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect("addreel");
            this._endCallback = success;
            this.node.scale = 0.5;
            cc.tween(this.node)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(1);

            this.StartMove();
            Global.SlotsSoundMgr.playEffect("addreelrun");
            this.SetSlotsResult(cc.vv.gameData.getGameInfo().secretInfo.extraCards);
            cc.vv.gameData.GetSlotsScript().addCount(this._row);
        })

    },

    CanStopSlot(){
        return cc.vv.gameData.getGameInfo().secretInfo.extraCards.length > 0;
    },

    async OnSpinEnd() {
        await cc.vv.gameData.awaitTime(1);

        Global.SlotsSoundMgr.playEffect("reeldown");
        cc.tween(this.node)
            .to(0.5, {scale: 0.85}, {easing: "backIn"})
            .call(()=>{
                cc.find("caise_kuang", this.node).active = false;
                cc.find("luoxia_lizi", this.node).active = true;
                cc.find("luoxia_lizi", this.node).getComponent(sp.Skeleton)
                    .setAnimation(0, this._row + "X" + this._row + "_lizi", true);
                cc.find("reels", this.node).active = false;
                cc.find("reels_bg", this.node).active = false;
            })
            .start();

        await cc.vv.gameData.awaitTime(1);

        this.node.active = false;
        if (this._endCallback) {
            this._endCallback();
        }
    },
});