/**
 * @description
 */

let WheelItemType = {
    FreeGame: 1,
    Jackpot: 2,
    FreeGameMult: 3
};

cc.Class({
    extends: cc.Component,
    properties:{
        items: [cc.Node],
        lundai: cc.Node,
        lundai_zhezhao: cc.Node,
        lundai_di: cc.Node,
        lundai_kuang: cc.Node,
        lundai_win: cc.Node,
        result: cc.Node,
        jiantou: cc.Node,

        _speed: 17,
        _count: 5,

        _startMove: false,
        _needStop: false,
        _backMove: false,

        _resultItem: null,        // 结果索引 从1开始
        _bottomPosX: 510,

        _successCallback: null,

        _secretInfo: null,
        _isCard: false,

        _isRegular: false,
    },

    startWheel(secretInfo, isRegular, isCard) {
        return new Promise(async (success)=>{
            this.reset();
            this._successCallback = success;
            this._isRegular = isRegular;
            this._secretInfo = secretInfo;
            this._startMove = true;
            this._resultItem = this.items[0];
            this._isCard = isCard;
            this.schedule(this.updateWheel, 0.005);

            Global.SlotsSoundMgr.playEffect("GoldReel");

            this.lundai.getComponent(sp.Skeleton).setAnimation(0, "B_lundai_intro", false);
            this.lundai.getComponent(sp.Skeleton).addAnimation(0, "B_lundai_idle", true);
            this.lundai_zhezhao.getComponent(sp.Skeleton).setAnimation(0, "B_lundai_intro", false);
            this.lundai_zhezhao.getComponent(sp.Skeleton).addAnimation(0, "B_lundai_idle", true);
            this.lundai_kuang.getComponent(sp.Skeleton).setAnimation(0, "B_lundai_intro", false);
            this.lundai_kuang.getComponent(sp.Skeleton).addAnimation(0, "B_lundai_idle", true);

            this.lundai_win.active = false;
            await cc.vv.gameData.awaitTime(0.5);
            this.lundai_win.active = true;
            this.lundai_win.getComponent(sp.Skeleton).setAnimation(0, "lundai_bo_b", true);
        });
    },

    updateWheel() {
        if (this._startMove) {
            if (this._count === 0 && this._resultItem.x === 0) {
                this._startMove = false;
                this.exitWheelGame();
                return;
            }

            for (let item of this.items) {
                if (item.x >= (this._bottomPosX + 170)) {
                    item.getComponent("ImgSwitchCmp").setIndex(this._isRegular ? Math.floor(Math.random() * 9) : Math.floor(Math.random() * 11));
                    item.x = -this._bottomPosX;
                    if (item === this._resultItem) {
                        this._count--;
                        if (this._count <= 0) {
                            this._count = 0;
                            item.getComponent("ImgSwitchCmp").setIndex(this.getResultIndex());
                        }
                    }
                }

                item.x += this._speed;

                if (item.x >= -85 && item.x <= 85) {
                    item.scale = 1.5;
                } else if (item.x >= -170 && item.x <= 170) {
                    item.scale = 1.3;
                } else {
                    item.scale = 1;
                }
            }
        }
    },

    getResultIndex() {
        let index = 0;
        if (this._isCard) {
            index = this._secretInfo.convertCard - 1;
        } else {
            if (this._secretInfo.upLevel > 0) {
                index = 8 + this._secretInfo.upLevel;
            } else {
                index = this._secretInfo.convertCard - 1;
            }
        }
        return index;
    },

    async exitWheelGame() {
        Global.SlotsSoundMgr.playEffect("GRstop");
        this.lundai_win.getComponent(sp.Skeleton).setAnimation(0, "lundai_win", false);
        this.lundai_di.active = true;
        this.result.active = true;
        this.result.getComponent("ImgSwitchCmp").setIndex(this.getResultIndex());

        await cc.vv.gameData.awaitTime(1);

        if (this._secretInfo.upLevel > 0 && !this._isCard) {
            Global.SlotsSoundMgr.playEffect("arrow");
            this.result.active = false;
            this.jiantou.active = true;
            this.jiantou.getComponent(sp.Skeleton).setAnimation(0, this._secretInfo.upLevel === 1 ? "lan_jiantou" : "huang_jiantou", false);
            await cc.vv.gameData.awaitTime(0.5);
        }

        if (this._successCallback) {
            this._successCallback();
        }
    },

    async resetToNormal() {
        this.result.active = true;
        this.jiantou.active = false;
        this.lundai_di.active = false;
        this.lundai.getComponent(sp.Skeleton).setAnimation(0, "S_lundai_intro", false);
        this.lundai.getComponent(sp.Skeleton).addAnimation(0, "S_lundai_idle", true);
        this.lundai_zhezhao.getComponent(sp.Skeleton).setAnimation(0, "S_lundai_intro", false);
        this.lundai_zhezhao.getComponent(sp.Skeleton).addAnimation(0, "S_lundai_idle", true);
        this.lundai_kuang.getComponent(sp.Skeleton).setAnimation(0, "S_lundai_intro", false);
        this.lundai_kuang.getComponent(sp.Skeleton).addAnimation(0, "S_lundai_idle", true);
        for (let item of this.items) {
            cc.tween(item)
                .to(0.5, {scale: 1})
                .start();
        }
        this.lundai_win.active = false;
        await cc.vv.gameData.awaitTime(0.5);
        this.lundai_win.active = true;
        this.lundai_win.getComponent(sp.Skeleton).setAnimation(0, "lundai_bo_s", true);

        await cc.vv.gameData.awaitTime(0.5);
    },

    reset() {
        this._startMove = false;
        this._speed = 17;
        this._count = 5;
    },
});