/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _dollarNum: 0,
    },

    Init() {
        this._super();

        this._gold_reel = cc.find("gold_reel", this.node.parent);

        let deskInfo = cc.vv.gameData.getDeskInfo();

    },

    //点击旋转按钮调用
    StartMove: function () {
        this._super();
        Global.SlotsSoundMgr.playNormalBgm();
        cc.find("reels_frame/frame", this.node).active = true;
        cc.find("reels_frame/frame_2", this.node).active = false;
        cc.find("reels_frame/frame_4", this.node).active = false;
        for (let reel of this._reels) {
            reel.StartRecycleSymbol(0.1);
        }
        this.ClearAllTopShow();
    },

    async ReconnectShow() {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        let rest = cc.vv.gameData.GetFreeTime()
        if (rest) {
            await cc.vv.gameData.awaitTime(0.2);
            this.ShowGameview(true);
            for (let i = 0; i < 10; i++) {
                let jp = cc.find("collect_node/jp_" + (i + 1), this.node);
                cc.find("gold", jp).active = i < deskInfo.freeGameInfo.bonusCnt;
            }
            this._dollarNum = deskInfo.freeGameInfo.bonusCnt;

            await cc.vv.gameData.awaitTime(0.5);

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("fgbgm");

            this.CanDoNextRound()
        } else {
            this.ShowGameview(false);

            this.CanDoNextRound();
            if (deskInfo.needbet > deskInfo.currmult) {
                this.popBetupDialog();
            }
        }
    },

    async onMsgSpine(msg) {
        this._super(msg);
        if (this.CheckEnterFreeGame() && Math.random() < 0.1) {
            this.SetStopTime(4);
            this.showBigAward();
        }

        if ((cc.vv.gameData.GetGameWin() / cc.vv.gameData.GetTotalBet() > 10) && Math.random() < 0.5) {
            this.SetStopTime(4);
            this.showBigAward();
        }
    },

    //检查进入免费
    CheckEnterFreeGame: function () {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === cc.vv.gameData.GetTotalFree();
    },

    CheckExitFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === 0;
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace: function () {
        this._super();
    },

    //重写：显示bonus中奖
    async OnSpinEnd() {
        if (this._gameInfo.secretInfo) {
            await cc.vv.gameData.awaitTime(1);
            let deskInfo = cc.vv.gameData.getDeskInfo();
            await this._gold_reel.getComponent("BasketballKing_Wheel")
                .startWheel(this._gameInfo.secretInfo, deskInfo.needbet > deskInfo.currmult, false);
            if (this._gameInfo.secretInfo.upLevel > 0) {
                await cc.vv.gameData.awaitTime(2);
                await this._gold_reel.getComponent("BasketballKing_Wheel").resetToNormal();

                let node = this._gameInfo.secretInfo.upLevel === 1 ?
                    cc.find("slots_2", this.node.parent) : cc.find("slots_4", this.node.parent);
                let script = node.getComponent("BasketballKing_ExtraSlots");
                if (!script) {
                    script = node.addComponent("BasketballKing_ExtraSlots");
                }
                cc.vv.gameData.setExtraSlotsScript(script);
                cc.vv.gameData.setIsExtraSlots(true);
                node.active = true;
                script.Init(this._gameInfo.secretInfo.upLevel === 1 ? 2 : 4);
                await script.startSlot();

                await cc.vv.gameData.awaitTime(1);

                await this._gold_reel.getComponent("BasketballKing_Wheel")
                    .startWheel(this._gameInfo.secretInfo, deskInfo.needbet > deskInfo.currmult, true);

                Global.SlotsSoundMgr.playEffect("flyDown");
                for (let i = 0; i < this._gameInfo.secretInfo.cards.length; i++) {
                    if (this._gameInfo.secretInfo.cards[i] === this._cfg.questionMarkId) {
                        let idx = i + 1;
                        let fly_icon = cc.instantiate(cc.find("fly_icon", this.node.parent));
                        fly_icon.active = true;
                        fly_icon.parent = this.node.parent;
                        fly_icon.getComponent("ImgSwitchCmp").setIndex(this._gameInfo.secretInfo.convertCard - 1);
                        let startPos = cc.find("lundai/wheel/wheel_mask/index_1", this._gold_reel).convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                        fly_icon.position = startPos;
                        let symbol = this.GetSymbolByIdx(idx);
                        let endPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                        cc.tween(fly_icon)
                            .to(0.5, {position: endPos})
                            .call(() => {
                                symbol.setAnimationToTop(false);
                                symbol.ShowById(this._gameInfo.secretInfo.convertCard);
                            })
                            .removeSelf()
                            .start();
                    }
                }


                await cc.vv.gameData.awaitTime(0.5);
                await this._gold_reel.getComponent("BasketballKing_Wheel").resetToNormal();
                cc.vv.gameData.setIsExtraSlots(false);

            } else {
                Global.SlotsSoundMgr.playEffect("flyDown");
                for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
                    if (this._gameInfo.resultCards[i] === this._cfg.questionMarkId) {
                        let idx = i + 1;
                        let fly_icon = cc.instantiate(cc.find("fly_icon", this.node.parent));
                        fly_icon.active = true;
                        fly_icon.parent = this.node.parent;
                        fly_icon.getComponent("ImgSwitchCmp").setIndex(this._gameInfo.secretInfo.convertCard - 1);
                        let startPos = cc.find("lundai/wheel/wheel_mask/index_1", this._gold_reel).convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                        fly_icon.position = startPos;
                        let symbol = this.GetSymbolByIdx(idx);
                        let endPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                        cc.tween(fly_icon)
                            .to(0.5, {position: endPos})
                            .call(() => {
                                symbol.setAnimationToTop(false);
                                symbol.ShowById(this._gameInfo.secretInfo.convertCard);
                            })
                            .removeSelf()
                            .start();
                    }
                }

                await cc.vv.gameData.awaitTime(0.5);
                await this._gold_reel.getComponent("BasketballKing_Wheel").resetToNormal();
            }

        }

        this.ShowWinTrace();

        let winCoin = cc.vv.gameData.GetGameWin();
        let totalWinCoin = cc.vv.gameData.GetGameWin();
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            // 免费中
            totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin();
        }

        this.ShowBottomWin(winCoin, totalWinCoin, true, async () => {
            if (this.CheckEnterFreeGame()) {
                this.triggerFreeGame();
            } else {
                if (this.CheckExitFreeGame()) {
                    this.triggerExitFreeGame();
                } else {
                    this.CanDoNextRound();
                }
            }
        });
    },

    async addCount(row) {
        cc.find("reels_frame/frame", this.node).active = false;
        cc.find("reels_frame/frame_2", this.node).active = row === 2;
        cc.find("reels_frame/frame_4", this.node).active = row === 4;
        for (let reel of this._reels) {
            reel.AddCount(row, 0.1);
        }

        await cc.vv.gameData.awaitTime(0.2);

        let cards = this._gameInfo.secretInfo.cards;
        let acRow = cards.length / this._col
        let reelResults = []
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if (this._cfg.symbol[cards[i]]) {
                let res = {}
                res.sid = cards[i] //符号id
                if (!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            for (let j = 0; j < acRow; j++) {
                let symbol = item.GetSymbolByRow(j);
                if (reelRes[j] !== this._cfg.questionMarkId) {
                    symbol.ShowById(reelRes[j].sid);
                }
            }
        }
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        this._super(bFree);

        cc.find("collect_node", this.node).active = bFree;
        cc.find("collect_node/kuang", this.node).active = false;
    },

    GetSymbolByIdx: function (idx) {
        let col = (idx - 1) % this._col //考虑到变行，所以行可能有变化
        let row;
        if (this._gameInfo.secretInfo && this._gameInfo.secretInfo.upLevel > 0) {
            row = this._gameInfo.secretInfo.cards.length / this._col - Math.floor((idx - 1) / this._col) - 1;
        } else {
            row = this._gameInfo.resultCards.length / this._col - Math.floor((idx - 1) / this._col) - 1;
        }
        return this._reels[col].GetSymbolByRow(row)
    },

    //单列停止
    //colIdx:0开始
    //回弹动作执行之 前的停止时机
    OnReelSpinEnd: function (colIdx) {
        let reel = this._reels[colIdx];
        let hasQuestionMark = false;
        for (let i = 0; i < this._cfg.row; i++) {
            let symbol = reel.GetSymbolByRow(i);
            if (symbol.GetShowId() === this._cfg.questionMarkId) {
                hasQuestionMark = true;
                Global.SlotsSoundMgr.playEffect("reelquset");
                symbol.playWinAnimation();
                let fly_wenhao = cc.instantiate(cc.find("fly_wenhao", this.node.parent));
                fly_wenhao.active = true;
                fly_wenhao.parent = this.node.parent;
                let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                fly_wenhao.position = startPos;
                let endPos = cc.find("lundai/wheel/wheel_mask/index_1", this._gold_reel).convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                cc.tween(fly_wenhao)
                    .to(0.5, {position: endPos, scale: 1.1})
                    .to(0.2, {scale: 1})
                    .call(() => {
                        cc.find("lundai/wheel/wheel_mask/index_1", this._gold_reel)
                            .getComponent("ImgSwitchCmp").setIndex(11);
                    })
                    .removeSelf()
                    .start();
            }

            if (symbol.GetShowId() === this._cfg.dollarId) {
                symbol.playWinAnimation();
                Global.SlotsSoundMgr.playEffect("jpfly");
                let fly_dollar = cc.instantiate(cc.find("fly_dollar", this.node.parent));
                fly_dollar.active = true;
                fly_dollar.parent = this.node.parent;
                let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                fly_dollar.position = startPos;
                let endPos = cc.find("collect_node", this.node).convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                cc.tween(fly_dollar)
                    .to(0.5, {position: endPos})
                    .call(() => {
                        this.addDollar();
                    })
                    .removeSelf()
                    .start();
            }
        }

        if (hasQuestionMark) {
            Global.SlotsSoundMgr.playEffect("flyUP");
        }
    },

    addDollar() {
        this._dollarNum++;
        let jackpot = this.getTargetJackpot();
        let collect_node = cc.find("collect_node", this.node);
        cc.find("collect", collect_node).getComponent(sp.Skeleton)
            .setAnimation(0, "dian_collect", false);
        cc.find("target", collect_node).getComponent(cc.Label).string = jackpot.targetNum;
        cc.find("num", collect_node).getComponent(cc.Label).string = this._dollarNum;
        for (let j = 0; j < 10; j++) {
            cc.find("jp_" + (j + 1) + "/gold", collect_node).active = j < this._dollarNum;
        }
        cc.find("prize", collect_node).getComponent("ImgSwitchCmp").setIndex(jackpot.targetIndex);
    },

    getTargetJackpot() {
        let jackpotNeedNum = [7, 8, 9, 10];
        for (let i = 0; i < jackpotNeedNum.length; i++) {
            if (this._dollarNum < jackpotNeedNum[i]) {
                return {targetNum: jackpotNeedNum[i], targetIndex: i};
            }
        }
        return {targetNum: 10, targetIndex: 3};
    },

    async triggerFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        Global.SlotsSoundMgr.playEffect("triggering");

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === this._cfg.scatterId) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        // 触发免费游戏
        await cc.vv.gameData.awaitTime(2);

        await this.popFreeDialog();

        this.ShowGameview(true);
        this._dollarNum = 0;

        for (let i = 0; i < 10; i++) {
            let jp = cc.find("collect_node/jp_" + (i + 1), this.node);
            cc.find("gold", jp).active = false;
        }
        cc.find("collect_node/target", this.node).getComponent(cc.Label).string = 7;
        cc.find("collect_node/num", this.node).getComponent(cc.Label).string = 0;


        await cc.vv.gameData.awaitTime(0.5);

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("fgbm");
        this.CanDoNextRound();
    },

    StopMove() {
        if (cc.vv.gameData.getIsExtraSlots()) {
            cc.vv.gameData.getExtraSlotsScript().StopMove();
        } else {
            this._super();
        }
    },

    async triggerExitFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        await cc.vv.gameData.awaitTime(1);

        if (this._gameInfo.jackpot) {
            await this.popJackpotDialog();
        }

        await this.popFreeResultDialog();

        this.ShowGameview(false);

        await cc.vv.gameData.awaitTime(1);

        this.ShowBottomWin(cc.vv.gameData.GetGameTotalFreeWin(), cc.vv.gameData.GetGameTotalFreeWin(), true, () => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            this.CanDoNextRound();
        });
    },

    popFreeDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("fgbegin");
            let free_dialog = cc.find("dialog_node", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("common_enter_node", free_dialog);
            dialog.active = true;
            dialog.scale = 1;

            let freetanchuang = cc.find("freetanchuang", dialog);
            freetanchuang.scale = 0;
            cc.tween(freetanchuang)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let times = cc.find("times", freetanchuang);
            times.getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();

            await cc.vv.gameData.awaitTime(2);

            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    free_dialog.active = false;
                    dialog.active = false;
                    success();
                })
                .start();

        });
    },

    popFreeResultDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("fgend");

            let free_dialog = cc.find("dialog_node", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("result_node", free_dialog);
            dialog.active = true;
            dialog.scale = 1;

            let freetanchuang = cc.find("freetanchuang", dialog);
            freetanchuang.scale = 0;
            cc.tween(freetanchuang)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let yifenkuang = cc.find("yifenkuang", freetanchuang);
            cc.find("coin", yifenkuang).getComponent(cc.Label).string =
                Global.FormatNumToComma(cc.vv.gameData.GetGameTotalFreeWin());


            await cc.vv.gameData.awaitTime(2);


            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    free_dialog.active = false;
                    dialog.active = false;
                    success();
                })
                .start();

        })
    },

    async popJackpotDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("jpwin");

            cc.find("collect_node/kuang", this.node).active = true;

            let free_dialog = cc.find("dialog_node", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("jackpot_node", free_dialog);
            dialog.active = true;
            dialog.scale = 1;

            let freetanchuang = cc.find("freetanchuang", dialog);
            freetanchuang.scale = 0;
            cc.tween(freetanchuang)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let yifenkuang = cc.find("yifenkuang", freetanchuang);
            cc.find("coin", yifenkuang).getComponent(cc.Label).string =
                Global.FormatNumToComma(this._gameInfo.jackpot.value);

            cc.find("title", freetanchuang).getComponent("ImgSwitchCmp").setIndex(this._gameInfo.jackpot.id - 1);

            let btn_collect = cc.find("btn_collect", freetanchuang);
            btn_collect.active = false;
            cc.find("chaopiao", dialog).active = false;

            await cc.vv.gameData.awaitTime(1);

            Global.SlotsSoundMgr.playEffect("jp_celebration");
            cc.find("chaopiao", dialog).active = true;

            btn_collect.active = true;
            btn_collect.off("click");
            btn_collect.on("click", () => {
                btn_collect.off("click");

                Global.SlotsSoundMgr.stopEffectByName("jp_celebration");
                cc.tween(dialog)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(() => {
                        free_dialog.active = false;
                        dialog.active = false;
                        success();
                    })
                    .start();
            })
        });
    },

    async popBetupDialog() {
        this._bottomScript.ShowBtnsByState("moveing_1");
        let free_dialog = cc.find("dialog_node", this.node.parent);
        free_dialog.active = true;

        let dialog = cc.find("betup_node", free_dialog);
        dialog.active = true;
        dialog.scale = 1;

        let board = cc.find("betup_board", dialog);
        board.scale = 0;
        cc.tween(board)
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .start();

        let btn_power_mode = cc.find("btn_power_mode", board);
        let btn_regular_play = cc.find("btn_regular_play", board)

        await cc.vv.gameData.awaitTime(1);

        btn_power_mode.off("click");
        btn_power_mode.on("click", async () => {
            btn_power_mode.off("click");
            this._bottomScript.SetBetIdx(cc.vv.gameData.getDeskInfo().needbet);
            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    free_dialog.active = false;
                    dialog.active = false;
                    this.CanDoNextRound();
                })
                .start();
        });

        btn_regular_play.off("click");
        btn_regular_play.on("click", async () => {
            btn_regular_play.off("click");

            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    free_dialog.active = false;
                    dialog.active = false;
                    this.CanDoNextRound();
                })
                .start();
        });
    },

    showBigAward() {
        Global.SlotsSoundMgr.playEffect("bigAward");
        let big_award = cc.find("big_award", this.node.parent);
        big_award.active = true;
        let dajiangyugao = cc.find("dajiangyugao", big_award);
        dajiangyugao.getComponent(sp.Skeleton).setAnimation(0, "dajiangyugao", false);
        dajiangyugao.getComponent(sp.Skeleton).setCompleteListener(() => {
            dajiangyugao.getComponent(sp.Skeleton).setCompleteListener(null);
            big_award.active = false;
        });
        let chaopiao = cc.find("chaopiao", big_award);
        chaopiao.getComponent(sp.Skeleton).setAnimation(0, "chaopiao", true);
    },
});